import queue


def accepted(cap: int, xs: list[int]) -> int:
    """Count puts accepted by a bounded queue before it is full.

    Create a queue.Queue[int] holding at most cap items and try to put each
    element of xs in order without blocking (put_nowait). Stop at the first
    queue.Full and return the number of puts accepted so far. Nothing is ever
    taken from the queue. A cap of zero or less accepts nothing (it is not
    treated as unbounded).
    """
    if cap <= 0:
        return 0
    q: queue.Queue[int] = queue.Queue(maxsize=cap)
    count = 0
    for x in xs:
        try:
            q.put_nowait(x)
        except queue.Full:
            break
        count += 1
    return count


def test_stops_when_full() -> None:
    assert accepted(2, [10, 20, 30, 40]) == 2


def test_cap_larger_than_input() -> None:
    assert accepted(10, [1, 2, 3]) == 3


def test_cap_equals_len() -> None:
    assert accepted(3, [1, 2, 3]) == 3


def test_empty_input() -> None:
    assert accepted(5, []) == 0


def test_zero_capacity_accepts_nothing() -> None:
    assert accepted(0, [1, 2, 3]) == 0


def test_negative_capacity_accepts_nothing() -> None:
    assert accepted(-1, [1, 2]) == 0


def test_duplicates_are_counted() -> None:
    assert accepted(3, [7, 7, 7, 7, 7]) == 3


def test_capacity_one() -> None:
    assert accepted(1, [5, 6]) == 1


def test_does_not_mutate_input() -> None:
    xs = [1, 2, 3, 4]
    accepted(2, xs)
    assert xs == [1, 2, 3, 4]


def test_returns_int_type() -> None:
    assert isinstance(accepted(1, [1]), int)
    assert isinstance(queue.Queue(maxsize=1), queue.Queue)

